package com.signalchain.app.audio
import java.io.*;import java.nio.*;import kotlin.math.*
object WavLoader{
 data class LoadedAudio(val samples:FloatArray,val sampleRate:Int)
 fun load(path:String,targetSampleRate:Int=0):LoadedAudio{val f=RandomAccessFile(path,"r");require(String(ByteArray(4){f.readByte().toByte()})=="RIFF"){ "Only WAV files are supported." };f.skipBytes(4);require(String(ByteArray(4){f.readByte().toByte()})=="WAVE"){ "Invalid WAV file." };var fmt=0;var ch=0;var rate=0;var bits=0;var data=ByteArray(0);while(f.filePointer<f.length()){val id=String(ByteArray(4){f.readByte().toByte()});val size=Integer.reverseBytes(f.readInt());when(id){ "fmt "->{fmt=f.readUnsignedShort();ch=f.readUnsignedShort();rate=Integer.reverseBytes(f.readInt());f.skipBytes(6);bits=f.readUnsignedShort();if(size>16)f.skipBytes(size-16)};"data"->{data=ByteArray(size);f.readFully(data)};else->f.skipBytes(size)}};require(fmt==1||fmt==3){"Only PCM WAV files are supported."};require(ch>0&&bits==16||bits==32){"Only PCM16/PCM32 WAV files are supported."};val bb=ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN);val frames=data.size/(ch*(bits/8));val x=FloatArray(frames);for(i in 0 until frames){var sum=0.0;for(c in 0 until ch)sum+=if(bits==16)bb.short/32768.0 else bb.float.toDouble();x[i]=(sum/ch).toFloat()};val peak=x.maxOfOrNull{abs(it)}?:0f;for(i in x.indices)x[i]=(x[i]/(peak+1e-10)).toFloat();require(x.size>=.03*rate){"Audio is too short; upload at least 30 ms of audio."};return LoadedAudio(x,rate)}
}
